// Step-into-the-push reflex: adds the pelvis velocity error (body frame) to the operator command,
// so the policy steps in the direction the pelvis is being pushed.
import { Reflex, type ReflexState } from './reflex.js';

const GAIN = 1.0; // ratio, (m/s command) per (m/s velocity error)
const MAX_ADD = 0.6; // m/s, largest correction added per axis

const clamp = (v: number, m: number): number => Math.max(-m, Math.min(m, v));

export class KiroReflex extends Reflex {
  override command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const w = s.qpos[3] as number, x = s.qpos[4] as number, y = s.qpos[5] as number, z = s.qpos[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const vwx = s.qvel[0] as number, vwy = s.qvel[1] as number;
    const vbx = c * vwx + sn * vwy;
    const vby = -sn * vwx + c * vwy;
    const b0 = base[0] as number, b1 = base[1] as number;
    out[0] = b0 + clamp(GAIN * (vbx - b0), MAX_ADD);
    out[1] = b1 + clamp(GAIN * (vby - b1), MAX_ADD);
    out[2] = base[2] as number;
  }
}

